#!/usr/bin/env node
/**
 * Extracts the demo league the native app ships (apple/App/Demo/DemoLeagueData.swift,
 * itself generated by apple/Tools/make-demo-league.py) into public/demo/routes.json,
 * so the web demo serves exactly the same Sleeper responses.
 *
 * Reads the Swift file only; nothing under apple/ is written.
 *   node scripts/export-demo-league.mjs
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const root = fileURLToPath(new URL('..', import.meta.url))
const source = readFileSync(`${root}apple/App/Demo/DemoLeagueData.swift`, 'utf8')

// Entries look like:  "/v1/league/L1": ###"{...}"###,
const entry = /^\s*"(\/[^"]+)":\s*###"([\s\S]*?)"###,?$/gm
const routes = {}
for (const match of source.matchAll(entry)) {
  const [, path, body] = match
  JSON.parse(body) // every body must be valid JSON; throws with the path otherwise
  routes[path] = body
}
const count = Object.keys(routes).length
if (count === 0) throw new Error('no routes found in DemoLeagueData.swift — has its format changed?')

mkdirSync(`${root}public/demo`, { recursive: true })
writeFileSync(`${root}public/demo/routes.json`, JSON.stringify(routes))
console.log(`public/demo/routes.json: ${count} routes`)
